import Flutter
import UIKit
#if HUSK_ACMEWIDGETSDK
import AcmeWidgetSDK
#endif

public class AcmeWidgetPlugin: NSObject, FlutterPlugin {
  public static func register(with registrar: FlutterPluginRegistrar) {
    let channel = FlutterMethodChannel(name: "acme_widget", binaryMessenger: registrar.messenger())
    registrar.addMethodCallDelegate(AcmeWidgetPlugin(), channel: channel)
    // Generated by husk_sdk: answers AcmeWidgetSdkHusk.isAvailable() in Dart.
    AcmeWidgetSDKHuskChannel.register(with: registrar)
  }

  public func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
    switch call.method {
    case "greeting":
      let name = (call.arguments as? [String: Any])?["name"] as? String ?? "there"
      #if HUSK_ACMEWIDGETSDK
      result(AcmeWidget.greeting(for: name))
      #else
      result(FlutterError(code: "vendor_sdk_missing", message: "AcmeWidgetSDK is not linked into this build", details: nil))
      #endif
    default:
      result(FlutterMethodNotImplemented)
    }
  }
}
